//! Golden-corpus parity: the Rust recognizer must match the JS oracle exactly on
//! discrete outputs (kind/base/nC/secret/sideways/jutDir, ring closed/encloses/ccw)
//! and within a tiny tolerance on continuous scores. The corpus is generated by
//! `pnpm dump-corpus` (scripts/recognizer-oracle.mjs). If you change the
//! recognizer algorithm, regenerate the corpus deliberately and re-review.

use lorraine_atelier_lib::recognizer::{analyze_ring, classify, Pt};
use serde::Deserialize;

const CORPUS: &str = include_str!("corpus/recognizer.json");

#[derive(Deserialize)]
struct Corpus {
    classify: Vec<ClassifyCase>,
    ring: Vec<RingCase>,
}

#[derive(Deserialize)]
struct ClassifyCase {
    name: String,
    points: Vec<[f64; 2]>,
    expected: ClassifyExp,
}

#[derive(Deserialize)]
struct ClassifyExp {
    kind: String,
    base: String,
    #[serde(rename = "nC")]
    n_c: usize,
    score: f64,
    gap: f64,
    circ: f64,
    sideways: bool,
    #[serde(rename = "jutDir")]
    jut_dir: i32,
    secret: bool,
}

#[derive(Deserialize)]
struct RingCase {
    name: String,
    points: Vec<[f64; 2]>,
    center: [f64; 2],
    expected: RingExp,
}

#[derive(Deserialize)]
struct RingExp {
    closed: bool,
    encloses: bool,
    ccw: bool,
    score: f64,
    circ: f64,
    gap: f64,
}

fn to_pts(raw: &[[f64; 2]]) -> Vec<Pt> {
    raw.iter().map(|p| Pt { x: p[0], y: p[1] }).collect()
}

const SCORE_TOL: f64 = 1.0; // plan allows score ±1–2; sqrt/atan2 ULP diffs are far smaller
const CONT_TOL: f64 = 1e-6; // gap/circ are sqrt-based → effectively identical cross-engine

#[test]
fn recognizer_matches_js_oracle() {
    let corpus: Corpus = serde_json::from_str(CORPUS).expect("parse corpus");
    assert!(!corpus.classify.is_empty() && !corpus.ring.is_empty(), "empty corpus");

    for c in &corpus.classify {
        let got = classify(&to_pts(&c.points));
        let e = &c.expected;
        assert_eq!(got.kind, e.kind, "[{}] kind", c.name);
        assert_eq!(got.base, e.base, "[{}] base", c.name);
        assert_eq!(got.n_c, e.n_c, "[{}] nC", c.name);
        assert_eq!(got.secret, e.secret, "[{}] secret", c.name);
        assert_eq!(got.sideways, e.sideways, "[{}] sideways", c.name);
        assert_eq!(got.jut_dir, e.jut_dir, "[{}] jutDir", c.name);
        assert!((got.score - e.score).abs() <= SCORE_TOL, "[{}] score {} vs {}", c.name, got.score, e.score);
        assert!((got.gap - e.gap).abs() <= CONT_TOL, "[{}] gap {} vs {}", c.name, got.gap, e.gap);
        assert!((got.circ - e.circ).abs() <= CONT_TOL, "[{}] circ {} vs {}", c.name, got.circ, e.circ);
    }

    for c in &corpus.ring {
        let got = analyze_ring(&to_pts(&c.points), Pt { x: c.center[0], y: c.center[1] });
        let e = &c.expected;
        assert_eq!(got.closed, e.closed, "[{}] closed", c.name);
        assert_eq!(got.encloses, e.encloses, "[{}] encloses", c.name);
        assert_eq!(got.ccw, e.ccw, "[{}] ccw", c.name);
        assert!((got.score - e.score).abs() <= SCORE_TOL, "[{}] score {} vs {}", c.name, got.score, e.score);
        assert!((got.gap - e.gap).abs() <= CONT_TOL, "[{}] gap {} vs {}", c.name, got.gap, e.gap);
        assert!((got.circ - e.circ).abs() <= CONT_TOL, "[{}] circ {} vs {}", c.name, got.circ, e.circ);
    }
}
